<script lang="ts">
  import { ArrowLeft, ArrowRight, ExternalLink, Link, LogOut, Plus, Save, Settings, Shield, Trash2, Users } from '@lucide/svelte';
  import { goto, invalidateAll } from '$app/navigation';
  import type { PageData } from './$types';
  export let data: PageData;
  let updateText = '', linkLabel = '', linkUrl = '', notice = '', error = '', busy = false, showSettings = false;
  let pendingRoles: Record<string, string> = {};
  let visibility = { ...data.visibility };
  const visibilityLabels: Record<string, string> = { major: 'Major', graduationYear: 'Graduation year', bio: 'Bio', skills: 'Skills', interests: 'Interests', links: 'Profile links', previousProjects: 'Previous projects', avatar: 'Profile photo' };
  function initials(member: PageData['members'][number]) { return `${member.user.firstName?.[0] ?? '?'}${member.user.lastName?.[0] ?? ''}`.toUpperCase(); }
  async function postUpdate() { busy = true; notice = ''; error = ''; try { const response = await fetch(`/api/projects/${data.project.id}/updates`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ text: updateText }) }); const payload = await response.json(); if (!response.ok) throw new Error(payload.message); updateText = ''; notice = 'Update posted.'; await invalidateAll(); } catch (e) { error = e instanceof Error ? e.message : 'Could not post update.'; } finally { busy = false; } }
  async function addLink() { busy = true; notice = ''; error = ''; try { const response = await fetch(`/api/projects/${data.project.id}/workspace/links`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ label: linkLabel, url: linkUrl }) }); const payload = await response.json(); if (!response.ok) throw new Error(payload.message); linkLabel = ''; linkUrl = ''; notice = 'Team link added.'; await invalidateAll(); } catch (e) { error = e instanceof Error ? e.message : 'Could not add link.'; } finally { busy = false; } }
  async function removeLink(linkId: string) { if (!window.confirm('Remove this team link?')) return; const response = await fetch(`/api/projects/${data.project.id}/workspace/links`, { method: 'DELETE', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ linkId }) }); if (response.ok) await invalidateAll(); }
  async function saveVisibility() { busy = true; try { const response = await fetch(`/api/projects/${data.project.id}/workspace/profile-visibility`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify(visibility) }); const payload = await response.json(); if (!response.ok) throw new Error(payload.message); notice = 'Sharing settings saved.'; showSettings = false; await invalidateAll(); } catch (e) { error = e instanceof Error ? e.message : 'Could not save sharing settings.'; } finally { busy = false; } }
  async function leaveProject() { if (!window.confirm('Leave this project team? You will lose access to this workspace.')) return; const response = await fetch(`/api/projects/${data.project.id}/workspace/leave`, { method: 'POST' }); const payload = await response.json(); if (!response.ok) { error = payload.message; return; } await goto(`/projects/${data.project.id}`); }
  function chooseRole(memberId: string, accessRole: string) { pendingRoles = { ...pendingRoles, [memberId]: accessRole }; error = ''; notice = ''; }
  async function saveRole(memberId: string) { const accessRole = pendingRoles[memberId]; if (!accessRole) return; if (accessRole === 'owner' && !window.confirm('Transfer project ownership to this member? You will become an admin and can leave later.')) return; busy = true; error = ''; notice = ''; try { const endpoint = accessRole === 'owner' ? `/api/projects/${data.project.id}/ownership/transfer` : `/api/projects/${data.project.id}/members/${memberId}/role`; const response = await fetch(endpoint, { method: accessRole === 'owner' ? 'POST' : 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify(accessRole === 'owner' ? { memberId } : { accessRole }) }); const payload = await response.json(); if (!response.ok) throw new Error(payload.message); pendingRoles = Object.fromEntries(Object.entries(pendingRoles).filter(([id]) => id !== memberId)); notice = payload.message; await invalidateAll(); } catch (e) { error = e instanceof Error ? e.message : 'Could not save the team role.'; } finally { busy = false; } }
</script>

<svelte:head><title>{data.project.title} workspace — BuildTogether</title></svelte:head>
<div class="workspace-page">
  <header class="workspace-header"><a class="brand" href="/home"><span class="brand-mark brand-image"><img src="/brand/handshake-emblem.png" alt="" /></span><span>Build<span>Together</span></span></a><a class="back-link" href={`/projects/${data.project.id}`}><ArrowLeft size={15} /> Public project</a></header>
  <main class="workspace-main">
    <div class="workspace-kicker"><span class="private-pill"><Shield size={13} /> Private team workspace</span><span class="role-pill">{data.accessRole}</span></div>
    <div class="hero"><div><p class="eyebrow">{data.project.category} · {data.project.department}</p><h1>{data.project.title}</h1><p class="summary">{data.project.summary}</p></div><a class="button button-dark" href={`/projects/${data.project.id}/team`}><Users size={16} /> Manage team</a></div>
    {#if notice}<p class="notice" role="status">{notice}</p>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}
    <div class="workspace-grid">
      <section class="panel overview"><div class="panel-heading"><div><p class="eyebrow">Project overview</p><h2>What we’re building.</h2></div><span class="status">{data.project.status}</span></div><p>{data.project.summary}</p><div class="facts"><span><strong>{data.project.department}</strong>Area</span><span><strong>{data.project.hoursPerWeek}</strong>Commitment</span><span><strong>{data.project.location}</strong>Location</span></div>{#if data.project.roles?.length}<h3>Team roles</h3><div class="roles">{#each data.project.roles as role}<div><strong>{role.title}</strong><span>{role.peopleNeeded} needed</span><p>{role.description}</p></div>{/each}</div>{/if}</section>
      <section class="panel roster"><div class="panel-heading"><div><p class="eyebrow">Private roster</p><h2>Our team.</h2></div><span class="member-count">{data.members.length} members</span></div><p class="muted">Names and email addresses are visible to accepted team members.</p><div class="member-list">{#each data.members as member}<article class="member"><div class="avatar">{#if member.user.avatarUrl}<img src={member.user.avatarUrl} alt="" />{:else}{initials(member)}{/if}</div><div class="member-info"><div class="member-name"><strong>{member.user.firstName || member.user.lastName ? `${member.user.firstName} ${member.user.lastName}`.trim() : member.user.email}</strong><span class="role-tag">{pendingRoles[member.id] ?? member.accessRole}</span></div><a href={`mailto:${member.user.email}`}>{member.user.email}</a>{#if member.user.major}<small>{member.user.major}{member.user.graduationYear ? ` · Class of ${member.user.graduationYear}` : ''}</small>{/if}{#if member.user.bio}<p>{member.user.bio}</p>{/if}{#if member.user.skills.length}<div class="tags">{#each member.user.skills.slice(0, 5) as skill}<span>{skill}</span>{/each}</div>{/if}{#if data.accessRole === 'owner' && member.accessRole !== 'owner'}<label class="role-control">Team permission<select value={pendingRoles[member.id] ?? member.accessRole} onchange={(event) => chooseRole(member.id, (event.currentTarget as HTMLSelectElement).value)}><option value="member">Member</option><option value="admin">Admin</option><option value="owner">Owner</option></select>{#if pendingRoles[member.id] && pendingRoles[member.id] !== member.accessRole}<button class="save-role" type="button" onclick={() => saveRole(member.id)} disabled={busy}><Save size={12} /> {pendingRoles[member.id] === 'owner' ? 'Transfer ownership' : 'Save role'}</button>{/if}</label>{:else if data.accessRole === 'admin' && member.accessRole === 'member'}<label class="role-control">Team permission<select value={pendingRoles[member.id] ?? member.accessRole} onchange={(event) => chooseRole(member.id, (event.currentTarget as HTMLSelectElement).value)}><option value="member">Member</option><option value="admin" disabled>Admin</option></select>{#if pendingRoles[member.id] && pendingRoles[member.id] !== member.accessRole}<button class="save-role" type="button" onclick={() => saveRole(member.id)} disabled={busy}><Save size={12} /> Save role</button>{/if}</label>{/if}</div></article>{/each}</div></section>
      <section class="panel links-panel"><div class="panel-heading"><div><p class="eyebrow">Shared workspace</p><h2>Team links.</h2></div><Link size={20} color="var(--byui-blue)" /></div><p class="muted">Add GitHub repositories, Teams channels, Zoom rooms, docs, or anything the team uses.</p><div class="link-list">{#each data.workspaceLinks as link}<div class="team-link"><a href={link.url} target="_blank" rel="noreferrer"><ExternalLink size={15} /><span><strong>{link.label}</strong><small>{link.url}</small></span></a><button type="button" aria-label="Remove {link.label}" onclick={() => removeLink(link.id)}><Trash2 size={14} /></button></div>{:else}<p class="empty">No shared links yet.</p>{/each}</div><form class="link-form" onsubmit={(event) => { event.preventDefault(); addLink(); }}><input aria-label="Team link label" bind:value={linkLabel} placeholder="Label (e.g. GitHub repo)" required /><input aria-label="Team link URL" type="url" bind:value={linkUrl} placeholder="https://..." required /><button class="button button-outline" type="submit" disabled={busy}><Plus size={15} /> Add link</button></form></section>
      <section class="panel updates-panel"><div class="panel-heading"><div><p class="eyebrow">Collaboration log</p><h2>Project updates.</h2></div></div><div class="updates">{#each (data.project.updates ?? []).slice().reverse() as update}<article><p>{update.text}</p><small>{update.authorName} · {new Date(update.createdAt).toLocaleDateString('en-US')}</small></article>{:else}<p class="empty">No updates yet. Share the first milestone.</p>{/each}</div><form class="update-form" onsubmit={(event) => { event.preventDefault(); postUpdate(); }}><textarea bind:value={updateText} minlength="10" maxlength="1000" rows="3" placeholder="Share a progress update with the team..." required></textarea><button class="button button-dark" type="submit" disabled={busy}>{busy ? 'Saving…' : 'Post update'} <ArrowRight size={15} /></button></form></section>
      <section class="panel settings-panel"><div class="panel-heading"><div><p class="eyebrow">Workspace settings</p><h2>Team controls.</h2></div><Settings size={20} color="var(--byui-blue)" /></div><div class="settings-actions"><button type="button" onclick={() => showSettings = !showSettings}><Shield size={15} /> Choose profile details to share</button><button type="button" class="leave-button" onclick={leaveProject} disabled={data.accessRole === 'owner'}><LogOut size={15} /> {data.accessRole === 'owner' ? 'Owner cannot leave' : 'Leave project'}</button></div>{#if showSettings}<div class="visibility-box"><p>Choose what teammates can see. Your name and email are always shared with accepted members.</p>{#each Object.entries(visibilityLabels) as [key, label]}<label><input type="checkbox" bind:checked={visibility[key as keyof typeof visibility]} /> {label}</label>{/each}<button class="button button-dark" type="button" onclick={saveVisibility} disabled={busy}><Save size={15} /> Save sharing settings</button></div>{/if}</section>
    </div>
  </main>
</div>

<style>
  .workspace-page{min-height:100vh;background:#f6fbff;color:#102d3d;font-family:var(--byui-body)}.workspace-header{height:78px;padding:0 clamp(20px,6vw,80px);display:flex;align-items:center;justify-content:space-between;background:#fff;border-bottom:1px solid #dce7e9}.brand{text-decoration:none}.brand-image{width:46px;height:31px}.back-link{display:flex;align-items:center;gap:7px;color:var(--byui-deep-blue);font:700 12px var(--byui-display);text-decoration:none}.workspace-main{max-width:1180px;margin:auto;padding:52px 20px 90px}.workspace-kicker{display:flex;gap:8px;align-items:center}.private-pill,.role-pill,.status,.role-tag{display:inline-flex;align-items:center;gap:5px;border-radius:99px;padding:6px 10px;font:800 10px var(--byui-display);text-transform:uppercase}.private-pill{background:#dff1e8;color:#247356}.role-pill{background:#e8f4fb;color:var(--byui-deep-blue)}.hero{display:flex;align-items:end;justify-content:space-between;gap:20px;margin:28px 0 30px}.eyebrow{color:var(--byui-blue);font:800 10px var(--byui-display);letter-spacing:.14em;text-transform:uppercase;margin:0 0 9px}.hero h1{margin:0;color:#000;font:700 clamp(40px,6vw,70px)/.95 var(--byui-display);letter-spacing:-.06em}.summary{max-width:680px;color:#53656b;font-size:15px;line-height:1.6}.workspace-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(320px,.9fr);gap:16px}.panel{background:#fff;border:1px solid #dce7e9;border-radius:12px;padding:25px}.overview,.roster{min-height:300px}.links-panel,.updates-panel,.settings-panel{grid-column:1/-1}.panel-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:18px}.panel h2{margin:0;color:#000;font:700 25px var(--byui-display);letter-spacing:-.04em}.panel h3{color:var(--byui-deep-blue);font:700 15px var(--byui-display);margin:25px 0 12px}.panel>p,.muted{color:#63777d;font-size:13px;line-height:1.6}.status{background:#dff1e8;color:#247356}.member-count{color:#829197;font:700 12px var(--byui-display)}.facts{display:flex;flex-wrap:wrap;gap:22px;margin-top:23px;border-top:1px solid #e1e9eb;padding-top:17px}.facts span{display:grid;gap:4px;color:#829197;font-size:10px}.facts strong{color:var(--byui-deep-blue);font:700 12px var(--byui-display)}.roles,.member-list,.link-list,.updates{display:grid;gap:9px}.roles>div{padding:12px;border:1px solid #e1e9eb;border-radius:7px}.roles strong{display:block;color:var(--byui-deep-blue);font:700 13px var(--byui-display)}.roles span{color:#829197;font-size:10px}.roles p{color:#63777d;font-size:11px;line-height:1.5;margin:7px 0 0}.member-list{margin-top:17px}.member{display:flex;gap:11px;padding:12px 0;border-top:1px solid #e1e9eb}.avatar{width:40px;height:40px;flex:none;display:grid;place-items:center;border-radius:50%;background:var(--byui-light-blue);color:var(--byui-deep-blue);font:800 12px var(--byui-display);overflow:hidden}.avatar img{width:100%;height:100%;object-fit:cover}.member-info{min-width:0;flex:1}.member-name{display:flex;align-items:center;gap:7px;flex-wrap:wrap}.member-name strong{color:var(--byui-deep-blue);font:700 14px var(--byui-display)}.role-tag{padding:4px 7px;background:#f2edcf;color:#88691d;font-size:8px}.member-info>a{display:block;overflow-wrap:anywhere;color:var(--byui-blue);font-size:11px;margin-top:3px}.member-info small{display:block;color:#829197;font-size:10px;margin-top:5px}.member-info p{color:#63777d;font-size:11px;line-height:1.45;margin:8px 0 0}.tags{display:flex;flex-wrap:wrap;gap:5px;margin-top:8px}.tags span{padding:5px 7px;border-radius:4px;background:#e8f4fb;color:var(--byui-deep-blue);font:700 9px var(--byui-display)}.team-link{display:flex;justify-content:space-between;align-items:center;gap:10px;border-top:1px solid #e1e9eb;padding:12px 0}.team-link>a{display:flex;align-items:flex-start;gap:9px;color:var(--byui-blue);text-decoration:none}.team-link span{display:grid;gap:3px}.team-link strong{color:var(--byui-deep-blue);font:700 12px var(--byui-display)}.team-link small{max-width:700px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#829197;font-size:10px}.team-link button{border:0;background:none;color:#9c3030;cursor:pointer}.link-form{display:grid;grid-template-columns:.7fr 1.3fr auto;gap:8px;margin-top:16px}.link-form input,.update-form textarea{box-sizing:border-box;border:1px solid #c9d8df;border-radius:6px;padding:10px;background:#fff;font:13px var(--byui-body)}.link-form .button{justify-content:center}.updates article{border-top:1px solid #e1e9eb;padding:13px 0}.updates p{white-space:pre-wrap;color:#42555d;font-size:13px;line-height:1.55;margin:0 0 6px}.updates small{color:#829197;font-size:10px}.update-form{display:flex;gap:9px;margin-top:16px}.update-form textarea{flex:1;resize:vertical}.update-form .button{align-self:flex-end;white-space:nowrap}.settings-actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:18px}.settings-actions button{display:inline-flex;align-items:center;gap:6px;border:1px solid #c9d8df;border-radius:6px;background:#fff;color:var(--byui-deep-blue);padding:9px 12px;font:700 11px var(--byui-display);cursor:pointer}.settings-actions .leave-button{color:#9c3030}.settings-actions button:disabled{opacity:.55;cursor:not-allowed}.visibility-box{max-width:560px;margin-top:15px;padding:16px;background:#f7fbfd;border:1px solid #dce7e9;border-radius:8px}.visibility-box p{color:#63777d;font-size:12px;line-height:1.5}.visibility-box label{display:inline-flex;align-items:center;gap:6px;width:50%;margin:7px 0;color:var(--byui-deep-blue);font:700 11px var(--byui-display)}.visibility-box .button{margin-top:12px}.notice,.error{padding:10px 12px;border-radius:6px;font:700 11px var(--byui-display)}.notice{background:#dff1e8;color:#247356}.error{background:#fff0f0;color:#a32626}.empty{color:#829197;font-size:12px}.button{display:inline-flex;align-items:center;gap:7px;text-decoration:none}@media(max-width:800px){.hero{align-items:flex-start;flex-direction:column}.workspace-grid{grid-template-columns:1fr}.link-form{grid-template-columns:1fr}.update-form{align-items:stretch;flex-direction:column}.update-form .button{align-self:flex-start}.visibility-box label{width:100%}.workspace-header{padding:0 20px}}
  .role-control{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:10px;color:#829197;font-size:10px}.role-control select{border:1px solid #c9d8df;border-radius:5px;padding:5px;color:var(--byui-deep-blue);font:700 10px var(--byui-display)}.save-role{display:inline-flex;align-items:center;gap:4px;border:0;border-radius:5px;background:var(--byui-deep-blue);color:#fff;padding:6px 8px;font:700 9px var(--byui-display);cursor:pointer}.save-role:disabled{opacity:.55;cursor:wait}
</style>
